(window.webpackJsonp=window.webpackJsonp||[]).push([[92],{532:function(t,s,v){"use strict";v.r(s);var _=v(11),e=Object(_.a)({},(function(){var t=this,s=t.$createElement,v=t._self._c||s;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("p",[v("font",{attrs:{size:"5"}},[t._v("摘要：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("1、神会拯救他的百姓，所以要获得拯救，首先你得是神的百姓")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("2、神的百姓会对神的话起反应，会听神的话")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("3、神的百姓会完全认同神说的都是对的，会为自己的罪真实地悔改，也就是发生行为上的改变")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("4、神的百姓不会认为自己遵守神的律法能让自己获得救恩，而会去指望基督")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们平安。我们今天继续来讲路加福音的内容。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("上一次我们讲了路加福音3:1~20。今天我们继续停留在路加福音这段经文当中，从另外的角度来思考这段经文带给我们的信息。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("路加福音3:1~2节在介绍了大的历史背景之后，在第3节开始讲述施洗约翰的事工。这里说“他就来到约旦河一带地方，宣讲悔改的洗礼，使罪得赦。”紧接着，路加把他的这一事工和先知以赛亚书的预言联系在一起。我们来看第4节这里说“正如”先知以赛亚书上所记的话。这个“正如”，表示约翰来宣讲悔改的洗礼，使罪得赦，就应验了先知以赛亚书上的预言。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么先知以赛亚书上预言是什么呢？第4~5节说那里预言“在旷野有人声喊着说：‘预备主的道，修直他的路！一切山洼都要填满，大小山冈都要削平，弯弯曲曲的地方要改为正直，高高低低的道路要改为平坦。凡有血气的，都要见神的救恩。’”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这段话引自旧约以赛亚书40章。我们一起来看以赛亚书40：1~11节：")])],1),t._v(" "),v("p",[t._v("你们的神说：“你们要安慰，安慰我的百姓！ 2要对耶路撒冷说安慰的话，又向她宣告说，她争战的日子已满了，她的罪孽赦免了，她为自己的一切罪从耶和华手中加倍受罚。”3有人声喊着说：“在旷野预备耶和华的路，在沙漠地修平我们神的道！4一切山洼都要填满，大小山冈都要削平，高高低低的要改为平坦，崎崎岖岖的必成为平原。5耶和华的荣耀必然显现，凡有血气的必一同看见，因为这是耶和华亲口说的。”6有人声说：“你喊叫吧！”有一个说：“我喊叫什么呢？”说：“凡有血气的尽都如草，他的美容都像野地的花。7草必枯干，花必凋残，因为耶和华的气吹在其上——百姓诚然是草！8草必枯干，花必凋残，唯有我们神的话必永远立定。”9报好信息给锡安的啊，你要登高山！报好信息给耶路撒冷的啊，你要极力扬声！扬声不要惧怕，对犹大的城邑说：“看哪，你们的神！” 10 主耶和华必像大能者临到，他的膀臂必为他掌权。他的赏赐在他那里，他的报应在他面前。 11 他必像牧人牧养自己的羊群，用膀臂聚集羊羔抱在怀中，慢慢引导那乳养小羊的。")]),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这里的上下文中我们可以看到，这是一段关于神的百姓要蒙拯救的信息。其中第3~4节就是路加在这里所引用的经文。施洗约翰就是那个在旷野呼喊的人。当他出现，开始他的事工，就意味着神马上就要临到了，而神的临到将带来对神百姓的拯救。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("今天，我们通过约翰的事工，来看一看要如何才能获得神的救恩。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("一、得是神的百姓")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们再次把目光回到路加福音3：3节，看一看约翰在旷野所呼喊的内容是什么。这里说他来到约旦河一带地方，“宣讲悔改的洗礼”，也就是说，他在呼吁当时的以色列人为了他们的罪悔改、接受洗礼。路加在第4节开始，用“正如”这个词，告诉我们他的这一“宣讲、呼吁”，就是以赛亚所预言的那个在旷野之人的“呼喊”；而他这一宣讲、呼吁的内容——也就是为他们的罪悔改、并因此接受洗礼，就是以赛亚书中预言的呼喊的内容“预备主的道，修直他的路！一切山洼都要填满，大小山冈都要削平，弯弯曲曲的地方要改为正直，高高低低的道路要改为平坦。凡有血气的，都要见神的救恩。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以约翰的事工是宣讲“悔改的洗礼”、是呼喊“要预备主的道、修直他的路”。那么直接而言，是谁来悔改、接受洗礼呢？谁来预备主的道、修直他的路呢？直接而言，不是约翰，而是那些听到约翰宣讲、呼喊的神的百姓。当他们为自己的罪认罪悔改，他们就在预备主的道、修直他的路。所以我们可以看到，为主所预备的路，其实就是每个人的心。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而约翰的信息不是他自己突发奇想而来的。3:2最后这里说“撒迦利亚的儿子约翰在旷野里，神的话临到他。”神是他的信息的源头，约翰只是一个神使用的传声筒，神使用他把自己的话带给他的百姓，让他们要悔改、接受洗礼、预备自己的心，而神的百姓对此就会有所反应，他们就会按照神的要求去悔改、接受洗礼、把自己的心预备好。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("并不是所有人都这样。我们看路加福音3：19~20节，希律听到约翰的信息，有没有悔改、接受洗礼呢？并没有。反而是把他收在监里。因为他不是神的羊。主耶稣在约翰福音10:27说：“我的羊听我的声音，我也认识他们，他们也跟着我”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这让我想起我这么多年从事教导事工的好几个经历来。在这些经历中，都是有人拿着神的道与我争论。情况往往是我说某某行为是犯罪，因此教会或者对方要做出改变，但对方就找各种理由说那不是犯罪；还有一次是对神最基本的属性的认识，我说圣经启示的是三位一体的神，圣父、圣子、圣灵三个位格，一个本体，三个位格之间同荣共尊；对方就是坚持圣子比圣父要小。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在这些争论中，双方你来我往，最后无一例外都是不欢而散。后来我明白了，一个人接受神的道，不是靠我们理性逻辑的辩论。神的羊就会听他的声音，不是他的羊，说再多，说得再有道理，他也不会接受。接受神的道不是靠逻辑，而是靠心。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，我想问你们的是，你们的心是怎么样的？你们是不是对神的声音有反应？是不是听从他的声音？你们是不是神的羊？要获得神的救恩，首先你得是神的百姓、神的羊。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("神的声音现在在哪里呢？首要的就是在这本圣经当中，其次就是在本着这本圣经对你们进行劝勉、鼓励、教训、督责、归正的兄弟姐妹们的话中。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以你在读这本书的时候，或者弟兄姐妹在本着圣经与你交流的时候，你就是在听神的话。然后你的心是怎么样的？如果你是神的羊，你的心就会对神的话有反应；这意味着你一边听，一边心里就会不断反省自己在神面前是处在什么位置、什么状态，自己有什么地方需要坚持，有什么地方需要改变；有什么该做的还没做，要立即去做；有什么做了的不能再做，要立即回头。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("不要忘了，神的救恩不是给所有人的，是给他的百姓的，要获得他的救恩，首先你得是神的百姓，你的心得对他的话起反应。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("二、得要彻底悔改")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("刚才我们说了，以赛亚预言这个在旷野中呼喊的人，他所呼喊的内容，就是施洗约翰所宣讲的悔改之道。我们再来看一看以赛亚所预言的这个内容，以此来理解约翰所讲的“悔改之道”到底是什么。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("路加福音3:4~6这里说，这位在旷野呼喊的人，他所呼喊的是：4‘预备主的道，修直他的路！5一切山洼都要填满，大小山冈都要削平，弯弯曲曲的地方要改为正直，高高低低的道路要改为平坦。6凡有血气的，都要见神的救恩。’")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这段话中第4节这里原文中用的是祈使语句，呼吁百姓认罪悔改，预备自己的心；第5节使用的是一个陈述语句，描述要预备自己的心到达一个什么状态。从第5节这个比喻我们可以看到，是“一切”的山洼、“一切”山冈、“一切”弯曲的地方，都要填满、削平、修直。也就是说，神的百姓不是仅仅为自己某个罪而认罪悔改，而是要为自己的“一切”罪认罪悔改。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("什么是罪？违背神的律法就是罪（约翰一书3:4）。所以为自己一切罪认罪悔改意味着什么呢？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("首先意味着，在价值观上完全接受神的律法。神的律法说什么是对，什么就是对；神的律法说什么是错，什么就是错。我的认识不同，是我错了，不是神错了。神的律法在哪里？就在这本圣经当中。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以弟兄姐妹们，你们是不是认同，这本圣经里面的价值观，完全是对的、你全部接受。不是挑挑拣拣，符合你胃口的就接受，不符合你胃口的就不接受？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我曾经在一个姐妹的婚礼上遇到一个慕道友，她常年参加一个国际教会的查经团契。我在席间和她聊起圣经来，她说她觉得圣经里面有很多很好的做人的道理，但是里面也有很多已经过时的观念——可能尤其是男女之间的关系的观念，就是妻子要顺服丈夫的观念。另外我有一个同学也是，她的婚姻生活并不幸福，和她的老公形同陌路。我给她讲了福音，她自己也买了一本圣经来研习，但是对于圣经中关于“妻子要顺服丈夫”的教导，坚决无法接受。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("有意思的是，我发现很多受过高等教育的女性，都对此难以接受。因为这些观念不仅与世界传递给他们的观念不同，更与他们的情感相违背。我跟我那个同学聊起这个事情，她真的是流着泪说，凭什么嘛。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("另外，我的妻子也是一个例子。她虽然对妻子与丈夫的关系可能比较好接受，但无法接受要把上帝看得高过家庭这样的观念。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("其实他们不明白也无法接受的是，面对神的的时候，首先你不是要去考虑处理人和人之间的关系，不是去处理妻子和丈夫的关系，不是去处理一个妈妈和孩子的关系，神不是给你一些心灵鸡汤般的生活指南；你在面对神的时候，首先要处理的，是你和上帝之间的关系，你是不是把神当作神，你是不是承认：神所说，都是对的；而你与之不同的观念，都是错的。因此曾经你按照这些错误的观念去行事为人的一切，那是干犯了神的律法，是犯罪、是轻慢这位宇宙的至高君王。你承认这一点，并为你的这一切犯罪的行为、心思意念感到后悔，这就是彻底认罪悔改的首先的一步。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以兄弟姐妹们，我要问你们，你们有没有？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("三、得要真实悔改")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们刚才讲了为自己一切罪认罪悔改，首先意味着在价值观上完全接受神的律法。但这只是一个方面。达致救恩的彻底认罪悔改，对一切山洼、山冈、道路的填满、削平、修正，还意味着这种认罪悔改要是真实的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("什么叫真实的认罪悔改呢？就是你不仅接受神的律法是对的，你还会真的去按照神的律法做。第一步和第二步之间，其实是个逻辑必然。如果你真的在价值观上完全接受了神的律法，你认可神说的一切都是对的，那么你必然就会按照对的去做，是不是？人总是去做自己认为正确的事情。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们看路加福音3:7~9节约翰对那些出来要接受他洗礼的人怎么说的呢？“7毒蛇的种类！谁指示你们逃避将来的愤怒呢？8你们要结出果子来，与悔改的心相称！不要自己心里说：‘有亚伯拉罕为我们的祖宗。’我告诉你们，神能从这些石头中给亚伯拉罕兴起子孙来。9现在斧子已经放在树根上，凡不结好果子的树就砍下来，丢在火里。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家看到没有？不仅要有悔改的心，还要能结出果子来与之相称。无论你的身份是什么，无论你对基督教有多熟悉，无论你是是信几代，如果不结好果子，都要砍下来，丢在火里。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("结果子，就是把你内心所认可的神的律法，通过你的行为去彰显出来。你既然认可了神的律法是对的，那么你自然就会按照神的律法去行。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以说，结出果子来，证明了你是真有悔改的心。没有果子，说明你悔改的心是假的，你可能自以为是真的，但实际上还是假的。假的悔改是不能获得拯救的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当时神的百姓非常清楚这一点，所以当他们听到约翰的督促，他们在3:10问他：“这样我们当做什么”？接下来，11约翰回答说：“有两件衣裳的，就分给那没有的，有食物的也当这样行。”12又有税吏来要受洗，问他说：“夫子，我们当做什么呢？”13约翰说：“除了例定的数目，不要多取。”14又有兵丁问他说：“我们当做什么呢？”约翰说：“不要以强暴待人，也不要讹诈人，自己有钱粮就当知足。””")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("曾经你们对穷人没有爱，不关心，这违背神的律法，是犯罪。你们既然承认这是犯罪，愿意悔改，那就应该实际去做出关心穷人的举动，有两件衣裳的，就分给那没有的，有食物的也当这样行。”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你们这些税吏，曾经靠着罗马政府的允许而通过税收为自己积累财富，任意多取，这违背神的律法，是犯罪。你们既然承认这是犯罪，愿意悔改，那就应该实际去改正自己的行为，除了罗马政府例定的数目，不要多取。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你们这些兵丁，曾经仗着自己的拳头强暴带人、讹诈人，这违背神的律法，是犯罪。你们既然承认这是犯罪，愿意悔改，那就应该实际去改正自己的行为，不要再去做这些事情。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家发现没有，当他们实际按照约翰说的这些去行动，他们会遭受什么？现世损失。那些关心穷人的，会损失衣服、食物；那些税吏、兵丁，他们的财富会减少。但这又如何？他们是神的百姓、神的羊，因此神就会赐给他们理性，他们通过简单的权衡计算就可以知道，和神的拯救相比，这些东西都不值一提。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果我们套用保罗在腓立比书3:7~8节的话说，就是“只是我先前以为与我有益的，我现在因神的拯救都当做有损的。不但如此，我也将万事当做有损的，因我以获得神的拯救为至宝。我已丢弃万事，看做粪土，为要得着神的拯救。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以弟兄姐妹们，我问你们，你们是否已经彻底认罪悔改了？是否在价值观上完全接受神的律法，这本圣经说的就是对的？你是否能向我证明你的这种“接受”是真实的？大家想一想。你能不能举出一个例子来，告诉我你已经结出了果子，与你悔改的心相称？你能不能告诉我一个你价值观因着神的律法而改变、因此行为也发生改变的例子来？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我再问你们，你现在是不是已经具备了神所赐的理性，所以能够通过简单的权衡计算，就知道舍弃神的救恩来获得现世的金钱、学位、工作、家庭，哪怕是诺贝尔奖，那简直是最为疯狂、愚蠢的选择？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果这些答案是否定的，那么我们应该恐惧战兢地向神祈求，让他帮助我们，有一颗真正悔改的心，并且结出果子来，让你自己看到这悔改的心是真实的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("四、得要指望基督")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("下面我们来讲得到拯救的最后一步，要指望基督。我们来看路加福音3:15节，这里说那些百姓们除了认罪悔改，还在指望基督的到来。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“基督”是一个希腊文音译过来的，这个希腊文对应的希伯来文是“弥赛亚”，意思是“那一位受膏者”。在旧约当中，神启示给以色列人，会有一位受膏者到来，把他们从外邦的压迫当中拯救出来，重新建立一个像大卫王国那样的神的国度。所以在当时犹太人的观念当中，基督的到来就意味着神的拯救不仅仅是近了，而是实际上就到了。所以他们不仅认罪悔改，还盼望着基督的到来。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当然，我们现在知道，基督实际做的事情，比当时犹太人所盼望的要大得多。他不是把神的百姓从外邦的压迫中拯救出来，把我们从罪的捆绑中拯救出来，把我们从魔鬼的权势下拯救出来，带我们进入到那属天的神的国度。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但是无论是今天的我们，还是约翰时代神的百姓，我们的认知有一点是相同的，就是被真正的拯救，不是靠着我们自己，而是由基督来完成的。所以我们得救的指望不是自己，而是他。不是我做得怎么样，我就得拯救；而是基督做了什么，我只是在他所做的事上有份而已。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们当然比约翰时代的犹太人更清楚基督做了什么。就是他活了没有罪的一生，但是却为神百姓的罪死在十字架上，替百姓们承担了他们的罪真正的代价——就是神的咒诅，并且第三天复活，还清了百姓们的罪债。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们前面讲了要获得救恩，需要我们彻底、真实地认罪悔改，但认罪悔改不能成为我们得救得的望,因为即使我们认罪悔改，但我们已经犯过的罪，公义的神不可能就这么算了。罪一定要有代价，罪的代价就是死。这个死是指永死，永远承受神的咒诅。但是现在耶稣替我们死了，是他来帮我实现了神的公义。因此我们的指望只在乎他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以我们现在不是套用，而是真正引用保罗在腓立比书3:7~8节的话说：只是我先前以为与我有益的，我现在因基督都当做有损的。不但如此，我也将万事当做有损的，因我以获得基督为至宝。我已丢弃万事，看做粪土，为要得着基督。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，得着基督就是得着拯救。我们曾经犯罪，我们以后也可能还会犯罪，但是我们得救不在于我们犯罪还是不犯罪，而是在于我们有基督。犯罪之后，认罪悔改，相信基督在十字架上已经为我们的罪承担了代价，没有什么能再定我们的罪了。有基督耶稣已经死了，而且从死里复活，现今在神的右边，替我们祈求。也没有什么能让我们与神的爱隔绝，因为我们只要在基督里，那里就有神的爱。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，这就是今天我想给大家分享的信息：你如何才能获得神的拯救。这不是你自己努力而来的，而是神的拣选，神的百姓、神的羊，就会获得神的拯救。神的百姓就会听神的话，对神的话有反应；就会预备自己的心，彻底、真实地认罪悔改；就会信靠基督，紧紧抓住基督不放手，其他任何东西与他相比，都不值一提，因为基督就是救恩。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以你是不是指望基督、是不是盼望基督？你确定吗？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们来看3:16~16，约翰对基督的到来是如何描述的。他说：“16我是用水给你们施洗。但有一位能力比我更大的要来，我就是给他解鞋带也不配，他要用圣灵与火给你们施洗。17他手里拿着簸箕，要扬净他的场，把麦子收在仓里，把糠用不灭的火烧尽了。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("百姓们盼着基督，因为基督来会给他们带来拯救。但是约翰却怎么说呢？在17节，他告诉百姓们，你们确定你们要盼望基督的到来？没错，他的到来会带来拯救。但是，注意，他的到来也会带来审判！那些麦子，会被收在仓里，得到拯救，而那些糠秕，不是被拯救，而是被审判！你们确定你们是麦子，而不是糠秕吗？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，我很确定我是麦子。我如何确定的？不是因为我做过一个决志祷告，不是因为我受了洗，也不是因为我每周上教会，每天读经、祷告。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而是因为我发现我自己非常关注神的律法到底说了什么，我想要按照神的律法去做事情；因8为我发现我完全同意，神的全部律法都是对的，我一切和律法违背的，都是错的，都是罪；因为我发现我为我的罪后悔，我努力去纠正我的行为，哪怕要付出代价；因为我发现我绝不相信我得救是因为我行了律法，我坚定地相信完全是基督在十字架上所做的事，才是我得救的保障。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么，你呢？你确定你是麦子吗？")])],1)])}),[],!1,null,null,null);s.default=e.exports}}]);